document.addEventListener('DOMContentLoaded',async()=>{const list=document.querySelector('#member-list');if(!list)return;try{const items=await fetch('data/members.json').then(r=>r.json());const render=cat=>{const filtered=items.filter(m=>cat==='ALL'||m.group===cat);list.innerHTML=filtered.map(m=>`<article class="member-profile">${m.image?`<div class="member-avatar"><img src="${m.image}" alt="${m.displayName}" loading="lazy"></div>`:'<div class="avatar-placeholder" aria-label="プロフィール画像未設定">RS</div>'}<p class="meta accent">${m.group} / ${m.role}</p><h2>${m.displayName}</h2><p class="muted">${m.department}</p><div class="member-socials">${['x','youtube'].filter(k=>m[k]).map(k=>`<a href="${m[k]}" target="_blank" rel="noopener noreferrer">${k.toUpperCase()}</a>`).join('')}</div></article>`).join('')};document.querySelectorAll('.filter').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('.filter').forEach(x=>x.classList.remove('active'));b.classList.add('active');render(b.dataset.filter)}));render('ALL')}catch{list.innerHTML='<p class="empty-state">メンバー情報を読み込めませんでした。</p>'}});
